-- Backend Engineering ("The Fracture") Act 4 -- "API Engineering" content.
-- 1 campaign, 2 operations, 12 missions (11 lessons + boss), following the
-- same campaigns -> operations -> missions -> dialogue -> objectives ->
-- challenges -> hints pattern as Act 1.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-be4', 'world-be-4', 'api-engineering', '4A - API Engineering', 'Ship real endpoints for city services and find out why three engineers can each write correct code and still hand back three incompatible contracts.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-be4-1', 'campaign-be4', 'shaping-the-resource', 'Shaping the Resource', 'What a resource actually is, how REST constrains an API, and the layers -- controller, service, repository -- that keep a request honest on its way to the database.', 1),
  ('operation-be4-2', 'campaign-be4', 'the-contract', 'The Contract', 'DTOs, validation, error handling, and the one consistent contract three engineers should have agreed on before any of them wrote a route.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-be4-01', 'world-be-4', 'campaign-be4', 'operation-be4-1', 'resources', 'Resources', 'Before any endpoint exists, something has to agree on what counts as a "thing" in this system. Three engineers are about to build three different answers.', 'beginner', ARRAY['forge','mira'], null, null, '{"type":"simulation","simulationId":"resource-modeling-sim"}'::jsonb, '{"xp":90,"credits":15}'::jsonb, false, 1),
  ('mission-be4-02', 'world-be-4', 'campaign-be4', 'operation-be4-1', 'rest-principles', 'REST Principles', 'REST isn''t a technology, it''s a set of constraints. Break one silently and the API still runs -- it just stops behaving the way every client will assume it does.', 'beginner', ARRAY['mira'], '{"requiredMissionIds":["mission-be4-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"rest-principles-sim"}'::jsonb, '{"xp":100,"credits":15}'::jsonb, false, 2),
  ('mission-be4-03', 'world-be-4', 'campaign-be4', 'operation-be4-1', 'crud', 'CRUD', 'Create, read, update, delete. Four operations cover almost everything an API needs to do to a resource -- if you map them onto HTTP correctly.', 'beginner', ARRAY['forge'], '{"requiredMissionIds":["mission-be4-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"crud-operations-sim"}'::jsonb, '{"xp":100,"credits":15}'::jsonb, false, 3),
  ('mission-be4-04', 'world-be-4', 'campaign-be4', 'operation-be4-1', 'route-design', 'Route Design', 'A URI is a name for a resource, not a sentence describing what to do to it. Get the hierarchy wrong and nothing about the API reads consistently again.', 'beginner', ARRAY['forge'], '{"requiredMissionIds":["mission-be4-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"route-design-sim"}'::jsonb, '{"xp":110,"credits":20}'::jsonb, false, 4),
  ('mission-be4-05', 'world-be-4', 'campaign-be4', 'operation-be4-1', 'controllers', 'Controllers', 'A controller''s only job is to translate an HTTP request into a call and a response back into HTTP. The moment it starts doing real work, the layer beneath it becomes untestable.', 'intermediate', ARRAY['mira'], '{"requiredMissionIds":["mission-be4-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"controllers-sim"}'::jsonb, '{"xp":120,"credits":20}'::jsonb, false, 5),
  ('mission-be4-06', 'world-be-4', 'campaign-be4', 'operation-be4-1', 'services', 'Services', 'The service layer is where business rules actually live -- the logic that would be true even if this API were a command-line tool instead.', 'intermediate', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be4-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"services-layer-sim"}'::jsonb, '{"xp":120,"credits":20}'::jsonb, false, 6),
  ('mission-be4-07', 'world-be-4', 'campaign-be4', 'operation-be4-2', 'repository-pattern', 'Repository Pattern', 'A repository''s job is to hide exactly how data gets persisted, so the service above it never has to know or care.', 'intermediate', ARRAY['forge'], '{"requiredMissionIds":["mission-be4-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"repository-pattern-sim"}'::jsonb, '{"xp":130,"credits":20}'::jsonb, false, 7),
  ('mission-be4-08', 'world-be-4', 'campaign-be4', 'operation-be4-2', 'dtos', 'DTOs', 'A DTO is a deliberate, minimal shape for data crossing a boundary -- not whatever the database happens to store.', 'intermediate', ARRAY['mira'], '{"requiredMissionIds":["mission-be4-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"dto-mapping-sim"}'::jsonb, '{"xp":130,"credits":25}'::jsonb, false, 8),
  ('mission-be4-09', 'world-be-4', 'campaign-be4', 'operation-be4-2', 'validation', 'Validation', 'Validation decides what''s even allowed to reach a service. Skip it at the edge and every layer behind it has to defend itself all over again.', 'intermediate', ARRAY['forge'], '{"requiredMissionIds":["mission-be4-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"validation-rules-sim"}'::jsonb, '{"xp":140,"credits":25}'::jsonb, false, 9),
  ('mission-be4-10', 'world-be-4', 'campaign-be4', 'operation-be4-2', 'error-handling', 'Error Handling', 'An unhandled error doesn''t just fail the request that caused it -- in the wrong place, it can take the whole process down with it.', 'intermediate', ARRAY['mira'], '{"requiredMissionIds":["mission-be4-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"error-handling-sim"}'::jsonb, '{"xp":140,"credits":25}'::jsonb, false, 10),
  ('mission-be4-11', 'world-be-4', 'campaign-be4', 'operation-be4-2', 'consistent-error-contracts', 'Consistent Error Contracts', 'Three engineers, three error shapes, one integration that has to somehow guess which one it''s going to get back.', 'intermediate', ARRAY['forge','mira'], '{"requiredMissionIds":["mission-be4-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"error-contract-sim"}'::jsonb, '{"xp":150,"credits":25}'::jsonb, false, 11),
  ('mission-be4-12', 'world-be-4', 'campaign-be4', 'operation-be4-2', 'the-broken-contract', 'The Broken Contract', 'Three engineers, three incompatible error shapes, and a client integration that had to guess which one it would get back. Judge each real response against the contract and define the one that should have existed from day one.', 'boss', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be4-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"broken-contract-boss-sim"}'::jsonb, '{"xp":400,"credits":85,"badgeIds":["broken-contract"],"skillXp":{"api_design":30}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-be4-01', 1, 'forge', 'New assignment: real endpoints for city services. Pothole reports, permit applications, dispatch units -- Forge Division is finally shipping an actual API, not just a runtime holding itself together.'),
  ('mission-be4-01', 2, 'forge', 'Three engineers are starting on three different services this week. Before any of them writes a route, they need to agree on the same basic thing: what is a resource?'),
  ('mission-be4-01', 3, 'mira', 'A resource is anything the API lets a client address and act on by name -- a noun, not a verb. Model that wrong on day one and every route built on top inherits the mistake.'),
  ('mission-be4-02', 1, 'mira', 'REST isn''t a technology, it''s a set of constraints: statelessness, a uniform interface, resources identified by URIs, representations transferred over that interface. Break one silently and the API still runs -- it just stops behaving the way clients assume.'),
  ('mission-be4-02', 2, 'mira', 'The three engineers all say they''re "building REST APIs." Let''s see if they agree on what that word actually requires.'),
  ('mission-be4-03', 1, 'forge', 'Four operations cover almost everything you''ll ever do to a resource: create, read, update, delete. CRUD. The trick isn''t remembering the acronym, it''s mapping each one onto HTTP correctly and not mixing them up under pressure.'),
  ('mission-be4-03', 2, 'forge', 'One of the three engineers already got this wrong in review -- used the wrong method for a delete-like action and didn''t notice until a client script cached a response it should never have cached.'),
  ('mission-be4-04', 1, 'forge', 'A URI names a resource. It''s not a sentence describing an action, and it''s not a dumping ground for query parameters that should''ve been part of the path.'),
  ('mission-be4-04', 2, 'forge', 'Nest resources the way they''re actually related -- a dispatch unit belongs to a district, a permit belongs to an applicant -- and the hierarchy reads itself. Get it backwards and nobody can guess a URI without reading docs.'),
  ('mission-be4-05', 1, 'mira', 'A controller has exactly one job: turn an incoming HTTP request into a plain function call, and turn that function''s result back into an HTTP response. Nothing else.'),
  ('mission-be4-05', 2, 'mira', 'One of the three services has a controller function that''s two hundred lines long -- parsing, validating, querying the database and formatting the response, all in one place. Find out what that costs.'),
  ('mission-be4-06', 1, 'mira', 'Pull the business logic out of the controller and it has to go somewhere. That somewhere is the service layer -- the rules that would still be true even if this were a command-line tool instead of an HTTP API.'),
  ('mission-be4-06', 2, 'forge', 'A permit needing at least one inspection before approval isn''t an HTTP concern. It''s true no matter how the request arrives. That''s how you tell a service rule from a controller''s job.'),
  ('mission-be4-07', 1, 'forge', 'A repository''s whole purpose is to hide how persistence actually happens -- Postgres today, something else in two years -- so the service above it never has to know or care.'),
  ('mission-be4-07', 2, 'forge', 'If a service function has raw SQL sitting in it next to business rules, the repository pattern didn''t fail. It just never got built.'),
  ('mission-be4-08', 1, 'mira', 'A database row and an API response are not the same thing, even when they look identical today. A DTO is the deliberate, minimal shape you choose to send across a boundary -- not whatever the table happens to store.'),
  ('mission-be4-08', 2, 'mira', 'Skip the DTO and the client is now coupled to your schema. Add an internal-only column to the permits table by accident and it ships straight to the browser.'),
  ('mission-be4-09', 1, 'forge', 'Validation''s job is to decide what''s even allowed to reach a service in the first place. Do it at the edge, once, and every layer behind it can trust the shape of what it receives.'),
  ('mission-be4-09', 2, 'forge', 'Skip it, and every layer starts defending itself independently against the same bad input -- which is exactly as fragile as it sounds.'),
  ('mission-be4-10', 1, 'mira', 'An unhandled error inside a request handler doesn''t just fail that one request. Miss it in the wrong place and it can crash the entire process, taking every other in-flight request down with it.'),
  ('mission-be4-10', 2, 'mira', 'Centralized error handling exists so one thrown exception, anywhere in the stack, always ends the same predictable way -- a caught error and a clean response, never a crash.'),
  ('mission-be4-11', 1, 'forge', 'Pulled three error responses from three different endpoints this week, all built by different engineers, all supposedly following the same API standard.'),
  ('mission-be4-11', 2, 'forge', 'One returns {"error": "not found"}. Another returns {"message": "Not Found", "code": 404}. A third just returns the raw string "Permit not found" with a 404 status and no JSON at all.'),
  ('mission-be4-11', 3, 'mira', 'None of those are wrong in isolation. They''re wrong together. A client integrating against this API has to write three different parsers for what should be one predictable shape.'),
  ('mission-be4-12', 1, 'mira', 'Every lesson this Act pointed at the same problem: three engineers, three services, three different ideas of what a "contract" even is.'),
  ('mission-be4-12', 2, 'forge', 'I pulled four real responses off the wire this week. Judge each one against the shape we designed last mission -- does it actually match, or does it just look close enough?'),
  ('mission-be4-12', 3, 'mira', 'Don''t patch anything today. Just tell me, for each one, whether it honors the contract -- and then give me the one rule that would make honoring it not optional.'),
  ('mission-be4-12', 4, 'forge', '...one more thing. The route table has an entry for /permits//history. Nobody registered that path on purpose -- the doubled slash again, same as the health check, same as the dispatch endpoint. It isn''t breaking anything. Logging it and moving on.'),
  ('mission-be4-12', 5, 'mira', 'Same as always: file it, don''t chase it today. Four services in and it still hasn''t caused a single failure. That''s exactly why I don''t like it.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-be4-01-o1', 'mission-be4-01', 1, 'Sort noun from verb', 'Decide which of these belong in the API as a resource, and which are actions performed on one.'),
  ('mission-be4-01-o2', 'mission-be4-01', 2, 'Name the identifier', 'Find the piece of evidence that shows the actual root cause of the inconsistent endpoints.'),
  ('mission-be4-02-o1', 'mission-be4-02', 1, 'Match the constraint', 'Match each REST constraint to the behavior that actually satisfies it.'),
  ('mission-be4-03-o1', 'mission-be4-03', 1, 'Map CRUD to HTTP', 'Match each CRUD operation to the HTTP method that''s meant to perform it.'),
  ('mission-be4-03-o2', 'mission-be4-03', 2, 'Spot the misuse', 'Find the evidence that explains the caching bug from code review.'),
  ('mission-be4-04-o1', 'mission-be4-04', 1, 'Order the resource hierarchy', 'Put the path segments in order from the top-level collection down to one specific nested unit.'),
  ('mission-be4-05-o1', 'mission-be4-05', 1, 'Find what a controller shouldn''t own', 'Debug a controller that''s doing far more than translating a request.'),
  ('mission-be4-06-o1', 'mission-be4-06', 1, 'Sort controller logic from service logic', 'Decide whether each responsibility belongs in the controller or the service.'),
  ('mission-be4-07-o1', 'mission-be4-07', 1, 'Draw the boundary', 'Order the layers from the HTTP request down to the actual data store.'),
  ('mission-be4-07-o2', 'mission-be4-07', 2, 'Spot the leak', 'Find the line where persistence detail leaks into a layer that shouldn''t know about it.'),
  ('mission-be4-08-o1', 'mission-be4-08', 1, 'Find the leaked field', 'Debug a response mapping that leaks an internal-only field straight through to the client.'),
  ('mission-be4-09-o1', 'mission-be4-09', 1, 'Judge the payload', 'Decide whether this incoming request should pass validation.'),
  ('mission-be4-09-o2', 'mission-be4-09', 2, 'Find the missing check', 'Find the evidence that explains how a clearly invalid permit reached the database anyway.'),
  ('mission-be4-10-o1', 'mission-be4-10', 1, 'Find the unguarded path', 'Debug a handler where a thrown error has no path to being caught.'),
  ('mission-be4-11-o1', 'mission-be4-11', 1, 'Design the one shape', 'Choose the error contract every endpoint should actually converge on.'),
  ('mission-be4-12-o1', 'mission-be4-12', 1, 'Response from /permits/{id}', 'Judge whether this response honors the agreed contract.'),
  ('mission-be4-12-o2', 'mission-be4-12', 2, 'Response from /districts/{id}/units', 'Judge whether this response honors the agreed contract.'),
  ('mission-be4-12-o3', 'mission-be4-12', 3, 'Response from /inspections/{id}', 'Judge whether this response honors the agreed contract.'),
  ('mission-be4-12-o4', 'mission-be4-12', 4, 'Define the contract', 'State the one universal error shape that would have prevented this incident.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-be4-01-o1-c1', 'mission-be4-01-o1', 1, 'drag_and_drop', 'Sort each term into resource or action.', '{"items":[{"id":"i1","text":"pothole report"},{"id":"i2","text":"submit a report"},{"id":"i3","text":"permit"},{"id":"i4","text":"approve a permit"},{"id":"i5","text":"dispatch unit"},{"id":"i6","text":"cancel a dispatch"}],"targets":[{"id":"t1","label":"Resource (a noun the API can address)"},{"id":"t2","label":"Action (something done to a resource)"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t1","i4":"t2","i5":"t1","i6":"t2"}}'::jsonb),
  ('mission-be4-01-o2-c1', 'mission-be4-01-o2', 1, 'investigation', 'Which piece of evidence points at the actual root cause, not just a symptom of it?', '{"evidence":[{"id":"ev1","label":"Endpoint list","detail":"POST /submitPotholeReport, POST /approveThePermitNow, GET /getDispatchUnitById"},{"id":"ev2","label":"Client complaint","detail":"\"Every endpoint has a different shape and I can''t tell what a resource even is here\""},{"id":"ev3","label":"Design note","detail":"One engineer named every endpoint after the action it performs instead of the resource it addresses"}],"question":"Which piece of evidence points at the actual root cause, not just a symptom of it?"}'::jsonb, '{"requiredEvidenceIds":["ev3"]}'::jsonb),

  ('mission-be4-02-o1-c1', 'mission-be4-02-o1', 1, 'drag_and_drop', 'Match each REST constraint to the behavior that actually satisfies it.', '{"items":[{"id":"c1","text":"Statelessness"},{"id":"c2","text":"Uniform interface"},{"id":"c3","text":"Resource identification"},{"id":"c4","text":"Self-descriptive messages"}],"targets":[{"id":"t1","label":"Each request carries everything needed to process it -- the server keeps no session between calls"},{"id":"t2","label":"Every resource is addressed the same consistent way, through the same small set of methods"},{"id":"t3","label":"Every resource has a stable URI a client can reference"},{"id":"t4","label":"The message itself states its content type and how to interpret it"}]}'::jsonb, '{"correctMapping":{"c1":"t1","c2":"t2","c3":"t3","c4":"t4"}}'::jsonb),

  ('mission-be4-03-o1-c1', 'mission-be4-03-o1', 1, 'drag_and_drop', 'Match each CRUD operation to the HTTP method that''s meant to perform it.', '{"items":[{"id":"m1","text":"Create"},{"id":"m2","text":"Read"},{"id":"m3","text":"Update (full replace)"},{"id":"m4","text":"Delete"}],"targets":[{"id":"t1","label":"POST"},{"id":"t2","label":"GET"},{"id":"t3","label":"PUT"},{"id":"t4","label":"DELETE"}]}'::jsonb, '{"correctMapping":{"m1":"t1","m2":"t2","m3":"t3","m4":"t4"}}'::jsonb),
  ('mission-be4-03-o2-c1', 'mission-be4-03-o2', 1, 'investigation', 'Which piece of evidence explains why the delete-like action produced a cached, stale result instead of actually running?', '{"evidence":[{"id":"ev1","label":"Route definition","detail":"GET /permits/482/revoke"},{"id":"ev2","label":"Client behavior","detail":"The browser''s HTTP cache silently reused an old response instead of hitting the server on the second click"},{"id":"ev3","label":"HTTP spec note","detail":"GET requests are safe and cacheable by default -- they''re not supposed to change anything"}],"question":"Which piece of evidence explains why the delete-like action produced a cached, stale result instead of actually running?"}'::jsonb, '{"requiredEvidenceIds":["ev1"]}'::jsonb),

  ('mission-be4-04-o1-c1', 'mission-be4-04-o1', 1, 'interactive_diagram', 'Order the path segments from the top-level collection down to one specific nested unit.', '{"diagramId":"route-hierarchy","hotspots":[{"id":"districts","label":"/districts","explanation":"The collection of all districts -- the top-level resource."},{"id":"district_id","label":"/districts/{id}","explanation":"One specific district, addressed by its identifier."},{"id":"units","label":"/districts/{id}/units","explanation":"The collection of dispatch units belonging to that one district."},{"id":"unit_id","label":"/districts/{id}/units/{unitId}","explanation":"One specific dispatch unit, nested inside the district it belongs to."}],"task":"Order the path segments from the top-level collection down to one specific nested unit."}'::jsonb, '{"correctOrderIds":["districts","district_id","units","unit_id"]}'::jsonb),

  ('mission-be4-05-o1-c1', 'mission-be4-05-o1', 1, 'code_debugging', 'Which single line shows the controller reaching straight into the database instead of delegating to a service?', '{"language":"javascript","code":"function createPermit(req, res) {\n  const { applicantName, address } = req.body;\n  if (!applicantName || applicantName.length < 2) {\n    return res.status(400).json({ error: \"invalid name\" });\n  }\n  const db = new Client(process.env.DATABASE_URL);\n  db.connect();\n  const result = db.query(\"INSERT INTO permits (name, address) VALUES ($1, $2)\", [applicantName, address]);\n  db.end();\n  res.status(201).json(result.rows[0]);\n}","question":"Which single line shows the controller reaching straight into the database instead of delegating to a service?"}'::jsonb, '{"requiredLineIds":["  const db = new Client(process.env.DATABASE_URL);"]}'::jsonb),

  ('mission-be4-06-o1-c1', 'mission-be4-06-o1', 1, 'drag_and_drop', 'Decide whether each responsibility belongs in the controller or the service.', '{"items":[{"id":"i1","text":"Parse the request body into a plain object"},{"id":"i2","text":"Reject a permit that has zero recorded inspections"},{"id":"i3","text":"Set the HTTP status code on the response"},{"id":"i4","text":"Calculate whether an applicant qualifies for an expedited permit"},{"id":"i5","text":"Read the Authorization header"}],"targets":[{"id":"t1","label":"Controller (HTTP-facing)"},{"id":"t2","label":"Service (business rule)"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t1","i4":"t2","i5":"t1"}}'::jsonb),

  ('mission-be4-07-o1-c1', 'mission-be4-07-o1', 1, 'interactive_diagram', 'Order the layers from the incoming HTTP request down to where data is actually stored.', '{"diagramId":"layered-architecture","hotspots":[{"id":"controller","label":"Controller","explanation":"Translates the HTTP request into a call and the result back into a response."},{"id":"service","label":"Service","explanation":"Applies business rules, independent of HTTP and independent of storage."},{"id":"repository","label":"Repository","explanation":"Knows how to persist and retrieve a resource -- and hides that detail from everything above it."},{"id":"database","label":"Database","explanation":"The actual data store the repository talks to."}],"task":"Order the layers from the incoming HTTP request down to where data is actually stored."}'::jsonb, '{"correctOrderIds":["controller","service","repository","database"]}'::jsonb),
  ('mission-be4-07-o2-c1', 'mission-be4-07-o2', 1, 'code_debugging', 'Which line shows the service reaching around the repository to talk to the database directly?', '{"language":"javascript","code":"class PermitService {\n  constructor(repository) {\n    this.repository = repository;\n  }\n  async approve(permitId) {\n    const permit = await this.repository.findById(permitId);\n    if (permit.inspections < 1) {\n      throw new Error(''needs at least one inspection'');\n    }\n    const result = await pool.query(''UPDATE permits SET status = $1 WHERE id = $2'', [''approved'', permitId]);\n    return result.rows[0];\n  }\n}","question":"Which line shows the service reaching around the repository to talk to the database directly?"}'::jsonb, '{"requiredLineIds":["    const result = await pool.query(''UPDATE permits SET status = $1 WHERE id = $2'', [''approved'', permitId]);"]}'::jsonb),

  ('mission-be4-08-o1-c1', 'mission-be4-08-o1', 1, 'code_debugging', 'Which line maps an internal-only database field straight into the public API response?', '{"language":"javascript","code":"function toPermitResponse(row) {\n  return {\n    id: row.id,\n    applicantName: row.applicant_name,\n    status: row.status,\n    internalReviewerNotes: row.internal_reviewer_notes,\n    createdAt: row.created_at,\n  };\n}","question":"Which line maps an internal-only database field straight into the public API response?"}'::jsonb, '{"requiredLineIds":["    internalReviewerNotes: row.internal_reviewer_notes,"]}'::jsonb),

  ('mission-be4-09-o1-c1', 'mission-be4-09-o1', 1, 'multiple_choice', 'A permit request arrives with an empty name and a negative unit count. Should it pass validation?', '{"question":"A permit request arrives with {\"applicantName\": \"\", \"address\": \"12 Rowan St\", \"unitCount\": -3}. Should it pass validation?","options":[{"id":"a","text":"Yes, all three fields are present"},{"id":"b","text":"No -- an empty name and a negative unit count both violate basic constraints, even though every field technically exists"},{"id":"c","text":"Yes, missing values are the only thing validation checks for"},{"id":"d","text":"Unknowable without querying the database"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be4-09-o2-c1', 'mission-be4-09-o2', 1, 'investigation', 'Which piece of evidence is the actual root cause of the invalid data reaching storage?', '{"evidence":[{"id":"ev1","label":"Route handler","detail":"router.post(''/permits'', createPermit) -- no validation middleware attached"},{"id":"ev2","label":"Database row","detail":"A permit record exists with unit_count = -3"},{"id":"ev3","label":"Service code","detail":"createPermit(data) inserts data directly into the permits table with no checks"}],"question":"Which piece of evidence is the actual root cause of the invalid data reaching storage?"}'::jsonb, '{"requiredEvidenceIds":["ev1"]}'::jsonb),

  ('mission-be4-10-o1-c1', 'mission-be4-10-o1', 1, 'code_debugging', 'This route has no try/catch and no error-handling middleware registered. Which line will crash the process instead of returning a clean error response?', '{"language":"javascript","code":"router.get(''/permits/:id'', async (req, res) => {\n  const permit = await repository.findById(req.params.id);\n  if (!permit) {\n    throw new Error(''permit not found'');\n  }\n  res.status(200).json(permit);\n});","question":"This route has no try/catch and no error-handling middleware registered. Which line will crash the process instead of returning a clean error response?"}'::jsonb, '{"requiredLineIds":["    throw new Error(''permit not found'');"]}'::jsonb),

  ('mission-be4-11-o1-c1', 'mission-be4-11-o1', 1, 'multiple_choice', 'Given the three inconsistent shapes Forge pulled, which single error contract should every endpoint converge on?', '{"question":"Given the three inconsistent shapes Forge pulled, which single error contract should every endpoint converge on?","options":[{"id":"a","text":"Whatever shape is fastest for that one engineer to implement that day"},{"id":"b","text":"A consistent object with a stable set of fields -- for example {\"error\": {\"code\": \"NOT_FOUND\", \"message\": \"Permit not found\"}} -- used on every endpoint, every time"},{"id":"c","text":"A raw string is fine as long as the status code is correct"},{"id":"d","text":"Each service should be free to define its own shape as long as it''s documented separately"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be4-12-o1-c1', 'mission-be4-12-o1', 1, 'multiple_choice', 'Endpoint /permits/482 returns 404 with a structured error object. Does this honor the agreed contract?', '{"question":"Endpoint /permits/482 returns 404 with body {\"error\": {\"code\": \"NOT_FOUND\", \"message\": \"permit 482 not found\"}}. Does this honor the agreed contract?","options":[{"id":"a","text":"Yes -- it matches the structured error-object shape exactly"},{"id":"b","text":"No -- it''s missing a top-level message field"},{"id":"c","text":"No -- 404 is the wrong status for a missing resource"},{"id":"d","text":"Unknowable without seeing the request"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-be4-12-o2-c1', 'mission-be4-12-o2', 1, 'multiple_choice', 'Endpoint /districts/12/units returns 500 with code and message floating at the top level. Does this honor the agreed contract?', '{"question":"Endpoint /districts/12/units returns 500 with body {\"message\": \"Internal Server Error\", \"code\": 500}. Does this honor the agreed contract?","options":[{"id":"a","text":"Yes, it has a message and a code, that''s close enough"},{"id":"b","text":"No -- it''s missing the error wrapper object entirely; code and message are floating at the top level, not nested where every client parser expects them"},{"id":"c","text":"Yes, because 500 is a valid status code"},{"id":"d","text":"No, because 500 errors are never supposed to include a body"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be4-12-o3-c1', 'mission-be4-12-o3', 1, 'investigation', 'Which evidence shows this response fails the contract worse than the previous two, which at least attempted a JSON shape?', '{"evidence":[{"id":"ev1","label":"Response body","detail":"Raw text \"Inspection not found\", not JSON at all"},{"id":"ev2","label":"Content-Type header","detail":"text/plain; charset=utf-8"},{"id":"ev3","label":"Status code","detail":"404"}],"question":"Which evidence shows this response fails the contract worse than the previous two, which at least attempted a JSON shape?"}'::jsonb, '{"requiredEvidenceIds":["ev1"]}'::jsonb),
  ('mission-be4-12-o4-c1', 'mission-be4-12-o4', 1, 'boss_encounter', 'Having judged all three responses, state the one universal error contract every endpoint must return.', '{"stages":[{"objectiveRef":"mission-be4-12-o1","label":"Response from /permits/{id}"},{"objectiveRef":"mission-be4-12-o2","label":"Response from /districts/{id}/units"},{"objectiveRef":"mission-be4-12-o3","label":"Response from /inspections/{id}"}],"task":"Having judged all three responses, state the one universal error contract every endpoint must return: a JSON body shaped like {\"error\": {\"code\": \"STRING_CODE\", \"message\": \"human-readable text\"}}, on every failure, enforced by a single shared error-handling layer instead of left to each engineer''s judgment."}'::jsonb, '{"requiredObjectiveIds":["mission-be4-12-o1","mission-be4-12-o2","mission-be4-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-be4-01-o1-c1', 'orientation', 'A resource is a thing you could look up later by name. An action is something you do to it once.', 10, 1),
  ('mission-be4-01-o1-c1', 'concept', 'If the word is a verb, or contains one ("submit", "approve", "cancel"), it''s describing an action, not naming a thing.', 20, 2),
  ('mission-be4-01-o1-c1', 'solution', 'Resources: pothole report, permit, dispatch unit. Actions: submit a report, approve a permit, cancel a dispatch.', 30, 3),
  ('mission-be4-01-o2-c1', 'orientation', 'Symptom vs cause: complaints and inconsistent endpoints are what you''d expect to see. Which evidence explains why?', 10, 1),
  ('mission-be4-01-o2-c1', 'concept', 'Naming an endpoint after a verb instead of a resource is the design decision that produces exactly this kind of inconsistency downstream.', 20, 2),
  ('mission-be4-01-o2-c1', 'solution', 'ev3: naming endpoints after actions instead of resources is the root design mistake -- everything else follows from it.', 30, 3),

  ('mission-be4-02-o1-c1', 'orientation', 'One of these is about memory (or the lack of it) between requests.', 10, 1),
  ('mission-be4-02-o1-c1', 'concept', 'Statelessness means no server-side session tied to a particular client between calls -- each request stands alone.', 20, 2),
  ('mission-be4-02-o1-c1', 'solution', 'Statelessness -> no session state between calls. Uniform interface -> consistent methods across resources. Resource identification -> stable URIs. Self-descriptive messages -> the message states how to interpret itself.', 30, 3),

  ('mission-be4-03-o1-c1', 'orientation', 'Three of these map to a method whose name is almost the same English word.', 10, 1),
  ('mission-be4-03-o1-c1', 'solution', 'Create -> POST, Read -> GET, Update (full replace) -> PUT, Delete -> DELETE.', 20, 2),
  ('mission-be4-03-o2-c1', 'orientation', 'GET is supposed to be safe -- safe enough that browsers and proxies are allowed to cache and even prefetch it.', 10, 1),
  ('mission-be4-03-o2-c1', 'concept', 'Using GET for an action with side effects breaks the safety assumption every cache, proxy and browser relies on.', 20, 2),
  ('mission-be4-03-o2-c1', 'solution', 'ev1: /permits/482/revoke was wired to GET, an operation that''s supposed to be side-effect-free and cacheable -- that''s why it got silently cached instead of executed again.', 30, 3),

  ('mission-be4-04-o1-c1', 'orientation', 'Start from the broadest collection and narrow one step at a time.', 10, 1),
  ('mission-be4-04-o1-c1', 'concept', 'Each step should either name a collection (plural, no id) or one member of it (with an id) -- never skip a level.', 20, 2),
  ('mission-be4-04-o1-c1', 'solution', '/districts, then /districts/{id}, then /districts/{id}/units, then /districts/{id}/units/{unitId}.', 30, 3),

  ('mission-be4-05-o1-c1', 'orientation', 'A controller translating HTTP is fine. A controller opening its own database connection is doing someone else''s job.', 10, 1),
  ('mission-be4-05-o1-c1', 'concept', 'If a controller function knows a connection string or a SQL query, it knows too much -- that logic belongs one layer down.', 20, 2),
  ('mission-be4-05-o1-c1', 'solution', 'const db = new Client(process.env.DATABASE_URL); -- the controller is instantiating a database client directly, which belongs in a service or repository, not here.', 30, 3),

  ('mission-be4-06-o1-c1', 'orientation', 'Ask whether the rule would still make sense if this system had no HTTP layer at all.', 10, 1),
  ('mission-be4-06-o1-c1', 'concept', 'Anything that mentions headers, status codes or the request/response objects directly is controller work. Anything that''s true regardless of transport is service work.', 20, 2),
  ('mission-be4-06-o1-c1', 'solution', 'Controller: parse the body, set the status code, read the header. Service: reject permits with zero inspections, calculate expedited eligibility.', 30, 3),

  ('mission-be4-07-o1-c1', 'orientation', 'Data doesn''t care about HTTP, and HTTP doesn''t care how data is stored -- there''s exactly one layer in between that should touch the database directly.', 10, 1),
  ('mission-be4-07-o1-c1', 'solution', 'Controller, then service, then repository, then the database itself.', 20, 2),
  ('mission-be4-07-o2-c1', 'orientation', 'The repository was injected into this service for a reason -- check whether it''s actually being used for the write.', 10, 1),
  ('mission-be4-07-o2-c1', 'concept', 'A raw query inside a service function means the service now knows the exact SQL dialect and schema -- exactly what the repository exists to hide.', 20, 2),
  ('mission-be4-07-o2-c1', 'solution', 'The service is running SQL directly through pool.query(...) instead of calling this.repository.approve(permitId), bypassing the abstraction it was given.', 30, 3),

  ('mission-be4-08-o1-c1', 'orientation', 'A DTO should be a deliberate allowlist, not everything the query happened to return.', 10, 1),
  ('mission-be4-08-o1-c1', 'concept', 'A field name containing "internal" is usually a signal it was never meant to leave the service boundary.', 20, 2),
  ('mission-be4-08-o1-c1', 'solution', 'internalReviewerNotes: row.internal_reviewer_notes -- this exposes an internal field to every client of the public API.', 30, 3),

  ('mission-be4-09-o1-c1', 'orientation', 'Presence and validity are two different checks -- a field can exist and still be garbage.', 10, 1),
  ('mission-be4-09-o1-c1', 'concept', 'An empty string is not a missing value, and a negative count is a semantically invalid one, even though the type matches.', 20, 2),
  ('mission-be4-09-o1-c1', 'solution', 'Every field is present, but an empty name and a negative unit count still violate basic constraints -- presence alone isn''t validity.', 30, 3),
  ('mission-be4-09-o2-c1', 'orientation', 'Something has to actually run the checks before the invalid row was ever written -- did it?', 10, 1),
  ('mission-be4-09-o2-c1', 'concept', 'A route with no validation middleware attached means nothing structural stood between the raw request body and the database write.', 20, 2),
  ('mission-be4-09-o2-c1', 'solution', 'ev1: the route has no validation middleware attached at all -- nothing was ever positioned to reject this input before it reached storage.', 30, 3),

  ('mission-be4-10-o1-c1', 'orientation', 'An async function that throws doesn''t automatically become a rejected promise something else is watching.', 10, 1),
  ('mission-be4-10-o1-c1', 'concept', 'Express doesn''t catch errors thrown inside an async handler by default -- without a try/catch or a wrapper that forwards to next(), the process itself is exposed.', 20, 2),
  ('mission-be4-10-o1-c1', 'solution', 'throw new Error(''permit not found''); -- with no try/catch and no error middleware in the chain, this throw has nowhere safe to land.', 30, 3),

  ('mission-be4-11-o1-c1', 'orientation', 'The problem was never any one shape being wrong -- it was three different shapes existing at all.', 10, 1),
  ('mission-be4-11-o1-c1', 'concept', 'A client should be able to write exactly one error parser and reuse it against every endpoint in the API, without a special case per service.', 20, 2),
  ('mission-be4-11-o1-c1', 'solution', 'A single, stable, structured error object used everywhere is the only option that lets one client parser handle every endpoint.', 30, 3),

  ('mission-be4-12-o1-c1', 'orientation', 'Check it field by field against the shape from last mission, not just at a glance.', 10, 1),
  ('mission-be4-12-o1-c1', 'solution', 'A nested error object with code and message, matching the agreed shape exactly.', 20, 2),
  ('mission-be4-12-o2-c1', 'orientation', 'Having a code and a message isn''t the same as having them in the right place.', 10, 1),
  ('mission-be4-12-o2-c1', 'solution', 'code and message exist but aren''t nested inside an error object -- a client parser written for the agreed shape won''t find them.', 20, 2),
  ('mission-be4-12-o3-c1', 'orientation', 'The first two at least tried to be JSON. This one didn''t.', 10, 1),
  ('mission-be4-12-o3-c1', 'solution', 'ev1: a raw text body with no JSON structure at all is the worst violation -- a JSON-parsing client would throw before it even got to check for an error field.', 20, 2),
  ('mission-be4-12-o4-c1', 'orientation', 'Look at what would have prevented all three problems at once, not three separate fixes.', 15, 1),
  ('mission-be4-12-o4-c1', 'solution', 'One universal shape -- a nested error object with code and message -- returned by a single shared error-handling layer every endpoint goes through, so no individual engineer''s judgment call can produce a fourth shape.', 25, 2);
